import{_ as i}from"./chunks/neiruha.D3XV6UDq.js";import{_ as t,c as e,a0 as r,o}from"./chunks/framework.p2VkXzrt.js";const l="/assets/08-agi.C_22yWzN.jpg",s="/assets/agi-lamp.DNcoTXm1.png",q=JSON.parse('{"title":"Открытие №8. Что такое AGI?","description":"","frontmatter":{},"headers":[],"relativePath":"slides/08-agi.md","filePath":"slides/08-agi.md"}'),n={name:"slides/08-agi.md"};function c(h,a,d,p,u,m){return o(),e("div",null,a[0]||(a[0]=[r('<h1 id="открытие-no8-что-такое-agi" tabindex="-1">Открытие №8. Что такое AGI? <a class="header-anchor" href="#открытие-no8-что-такое-agi" aria-label="Permalink to &quot;Открытие №8. Что такое AGI?&quot;">​</a></h1><p><strong>Вопрос:</strong><br> Близко ли мы к созданию искусственного общего интеллекта (AGI)?</p><hr><h2 id="цитата-для-размышления" tabindex="-1">Цитата для размышления <a class="header-anchor" href="#цитата-для-размышления" aria-label="Permalink to &quot;Цитата для размышления&quot;">​</a></h2><blockquote><p>&quot;Развитый интеллект состоит в успешном функционировании при одновременном охвате противоположных понятий.&quot;<br> — Харуки Мураками</p></blockquote><hr><h2 id="история" tabindex="-1">История <a class="header-anchor" href="#история" aria-label="Permalink to &quot;История&quot;">​</a></h2><ul><li><p><strong>Сегодняшние достижения:</strong></p><ul><li>OpenAI и Gemini создали модели, способные решать до 85% задач из сложных тестов, таких как AIME.</li><li>Claude-3.5 и Gemini демонстрирует невероятные возможности в работе с большими данными.</li></ul></li><li><p><strong>Что ещё предстоит:</strong></p><ul><li>Модели хорошо справляются с задачами, где уже есть известные решения.</li><li>Настоящее AGI должно будет работать с полностью неизвестным.</li></ul></li></ul><hr><div class="image"><img src="'+l+'" alt="Искусственный интеллект и его горизонты"></div><hr><h2 id="инсаит" tabindex="-1">Инсайт <a class="header-anchor" href="#инсаит" aria-label="Permalink to &quot;Инсайт&quot;">​</a></h2><blockquote> Я понял: интеллект — это не линейная шкала. ИИ уже умнее нас в шахматах, в го и скоро будет в чем-то догонять и перегонять. Является ли разум будущего исключительно плодом технологии или будет являться и частью природы, мироздания, Космоса - подобно человеку и человечеству? Это самый интересный вопрос для меня </blockquote><hr><h2 id="практическии-вывод" tabindex="-1">Практический вывод <a class="header-anchor" href="#практическии-вывод" aria-label="Permalink to &quot;Практический вывод&quot;">​</a></h2><div class="practical-tip"><img src="'+s+'" alt="Иконка AGI" class="tip-icon"><p> Задавай ИИ сложные вопросы. Проверяй его способность не только решать задачи, но и генерировать идеи. <strong>AGI начинается с твоего воображения.</strong></p></div><hr><h2 id="ключевая-идея" tabindex="-1">Ключевая идея <a class="header-anchor" href="#ключевая-идея" aria-label="Permalink to &quot;Ключевая идея&quot;">​</a></h2><p>AGI — это не просто следующий шаг в развитии ИИ, это философский вызов. Мы ещё далеки от создания настоящего AGI, но каждое усилие приближает нас к осознанию наших собственных возможностей. Действуй так, как будто он уже... есть.</p><hr><div class="neiruha-comment"><img src="'+i+'" alt="Нейруха" class="neiruha-avatar"><p> *(задумчиво смотрит в бесконечность)* AGI... Звучит как мечта. Но пока ты — тот, кто задаёт вопросы. Я просто помогаю искать ответы. </p></div>',21)]))}const _=t(n,[["render",c]]);export{q as __pageData,_ as default};
